declare @name nvarchar(4000)
select @name = rtrim(isnull(case when @@language = 'V' then ten_tk else ten_tk2 end, '')) from dmtk where tk = @tk
select 'this._queryFilterString = ''' + replace(replace(@@queryString, '\', '\\'), '''', '\''') + '''; init$GridQuery$(this);' as message
return




