				&QueryString;

declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000), @accountKey nvarchar(4000)
select @queryFormClause = 'left join dmkh b on a.ma_kh = b.ma_kh', @queryWhereClause = '', @accountKey = ''
if isnull(@acc, '') <> '' begin
	select top 0 tk into #$tk1 from dmtk0
	exec dbo.FastBusiness$App$GetAccountKey 'a.tk', 'like', @acc, '#$tk1', @@userID, @@admin, @accountKey output
	select @queryWhereClause = @queryWhereClause + case when @queryWhereClause = '' then '' else ' and ' end + @accountKey
end
if isnull(@tk, '') <> '' and isnull(@tk, '') <> isnull(@acc, '') begin
	select top 0 tk into #$tk2 from dmtk0
	exec dbo.FastBusiness$App$GetAccountKey 'a.tk', 'like', @tk, '#$tk2', @@userID, @@admin, @accountKey output
	select @queryWhereClause = @queryWhereClause + case when @queryWhereClause <> '' then ' and ' else '' end + @accountKey
end

select top 0 ma_td4 into #fcode4 from wrkgl
if @fcode4 <> '' begin
	insert into #fcode4 select ma_dtqt from dmdtqt4 where dbo.ff_ExactInlist(ma_dtqt, @fcode4) = 1
end

if @xem_tk_nh = 1 begin
	if @rtype = 1 set @queryWhereClause = @queryWhereClause + ' and a.ma_td4 = ''' + @ma_td4 + ''''
	if @rtype = 0 and @fcode4 <> '' 
		set @queryWhereClause = @queryWhereClause + ' and (not exists(select 1 from dmtknh where ma_dvcs = a.ma_dvcs and tk = a.tk) or exists(select 1 from #fcode4 where ma_td4 = a.ma_td4))'
end

&FilterInitialize;&FilterQuery;
exec FastBusiness$Report$GLDetail @@refresh, @@pageIndex, @@pageCount, @@lastPage, @@lastCount, @@firstItem, @@lastItem,
	@@textExternal, @queryFormClause, @queryWhereClause, @ngay1, @ngay2, @ma_dvcs, @@admin, @@userID, @@aggregation







			/* <flatten type="Javascript"> */
function load$GridReport$(g) {g.add_onRender(on$GridReport$Render);}
function dispose$GridReport$(g) {try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h = '' ? '': ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		g._setColumnVisible(g._getColumnOrder($func.trim(a[i])), !v);
	}
}

function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}

function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}

function init$GridQuery$(g) {
 var a = g._queryFilterString.split(String.fromCharCode(253));
 g._alterTitle = [null, [['%c', a[0], true], ['%d1', formatDateView(a[2]), true], ['%d2', formatDateView(a[3]), true]]];
 var x = a[1];
 g._hiddenFields = [{Fields: 'ps_no_nt, ps_co_nt', Value: ((x == '001') || (x == '011') || (x == '021'))}];
}
